//! Leptos: server-rendered with `to_html`, hydrated with `hydrate_body`.

use bench_common::COUNTER_START;
use leptos::prelude::*;

/// Library name, which names the files generated by wasm-bindgen.
pub const LIB: &str = "counter_leptos";

/// A button that increments the number next to it.
#[component]
pub fn App() -> impl IntoView {
    let count = RwSignal::new(COUNTER_START);
    view! {
        <button id="inc" on:click=move |_| *count.write() += 1>"+1"</button>
        <span id="count">{move || count.get()}</span>
    }
}

/// The server HTML.
#[cfg(not(target_arch = "wasm32"))]
pub fn page() -> String {
    let body = Owner::new().with(|| view! { <App/> }.to_html());
    bench_common::counter_page(LIB, &body)
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen::prelude::wasm_bindgen(start)]
pub fn start() {
    bench_common::mark("data-start");
    // Synchronous: listeners are attached when it returns.
    leptos::mount::hydrate_body(App);
    bench_common::mark("data-ready");
}
